<script setup lang="ts">
import { ref, computed } from 'vue'
import { Calendar, CircleCheck, AlarmClock, Warning, ArrowRight, Refresh } from '@element-plus/icons-vue'
import { api, query, items } from '../api'
import { useAuth } from '../stores/auth'
import { useLoad, monthRange, timeText } from '../composables'
import StatusTag from '../components/StatusTag.vue'
import AttendanceCharts from '../components/AttendanceCharts.vue'
const auth=useAuth(),range=ref<[string,string]>(monthRange()),summary=ref<any>(null),rows=ref<any[]>([])
const {loading,error,load}=useLoad(async()=>{const params={from:range.value[0],to:range.value[1]};const [s,r]=await Promise.all([api('/attendance/summary?'+query(params)),api('/attendance?'+query({...params,page:0,size:6}))]);summary.value=s;rows.value=items(r)})
const metrics=computed(()=>[{label:'应出勤天数',value:summary.value?.requiredDays,unit:'天',note:'按工作日历与在职区间计算',icon:Calendar},{label:'完成打卡天数',value:summary.value?.completedDays,unit:'天',note:'已完成签到及签退，含迟到早退',icon:CircleCheck},{label:'迟到 / 早退',value:summary.value?`${summary.value.lateCount} / ${summary.value.earlyCount}`:undefined,unit:'次',note:'迟到与早退分别统计',icon:AlarmClock},{label:'缺卡 / 缺勤',value:summary.value?`${summary.value.missingDays} / ${summary.value.absentDays}`:undefined,unit:'天',note:'日终后确认，不包含请假',icon:Warning}])
</script>
<template><div class="page-head"><div><div class="eyebrow">WORKSPACE OVERVIEW</div><h1>{{auth.isAdmin?'考勤概览':'我的工作台'}}</h1><p>掌握每一天的出勤，让工作更有条理。</p></div><div class="head-actions"><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" range-separator="—" start-placeholder="开始日期" end-placeholder="结束日期" :clearable="false" style="width:250px" @change="load"/><el-button :icon="Refresh" :loading="loading" circle aria-label="刷新概览" @click="load"/></div></div><div v-if="error" class="error-panel">{{error}}<el-button text @click="load">重试</el-button></div><div class="welcome-banner"><div><h2>{{auth.user?.name||auth.user?.username}}，今天也从容开始。</h2><p>{{auth.isAdmin?'人员、出勤与审批，都在同一个工作空间。':'查看个人出勤记录，及时提交请假和补卡申请。'}} 统计日期以北京时间为准。</p></div><el-icon class="welcome-art"><Calendar/></el-icon></div><div class="metric-grid" v-loading="loading"><div class="metric" v-for="metric in metrics" :key="metric.label"><div class="metric-label">{{metric.label}}<span class="metric-icon"><el-icon><component :is="metric.icon"/></el-icon></span></div><div class="metric-value">{{metric.value??'—'}}<small>{{metric.unit}}</small></div><div class="metric-note">{{metric.note}}</div></div></div><div class="summary-strip"><span>本期请假 <strong>{{summary?.leaveDays??'—'}}</strong> 天</span><span>批准补卡 <strong>{{summary?.correctionCount??'—'}}</strong> 次</span></div><AttendanceCharts :summary="summary"/><div class="panel"><div class="panel-head"><div><h2>考勤记录</h2><p>当前范围内的出勤明细</p></div><router-link to="/attendance"><el-button text type="primary">查看全部 <el-icon><ArrowRight/></el-icon></el-button></router-link></div><el-table :data="rows" v-loading="loading" empty-text="当前日期范围暂无考勤记录"><el-table-column label="员工" min-width="150"><template #default="{row}"><div class="name-cell"><span class="avatar">{{row.employeeName?.slice(0,1)}}</span><div>{{row.employeeName}}<small>{{row.employeeNo}}</small></div></div></template></el-table-column><el-table-column prop="date" label="日期" width="120"/><el-table-column prop="departmentName" label="部门" min-width="110"/><el-table-column label="签到" width="100"><template #default="{row}">{{timeText(row.checkIn)}}</template></el-table-column><el-table-column label="签退" width="100"><template #default="{row}">{{timeText(row.checkOut)}}</template></el-table-column><el-table-column label="状态" min-width="170"><template #default="{row}"><StatusTag :status="row.status" :late="row.late" :early="row.early"/></template></el-table-column></el-table></div><p class="footnote">完成打卡天数可包含迟到与早退。当前未结束工作日显示待完成，不提前计入缺勤。</p></template>
